    # --- Network (capability: network) ---
    def network_get(self, url, timeout_ms):
        """Outbound requests. Requires a network grant scoped to the host. Both calls return an HttpResult table (status, ok, headers, body, error, error_kind, truncated) rather than raising, so a script can branch on the outcome; headers is a newline-separated \'Name: value\' list. On a refusal, status is 0, error is a human string and error_kind is a stable machine-readable enum: \'\' on success, otherwise one of bad_url, refused (egress policy), not_granted (host outside the grant), transport, timeout, bad_redirect, too_many_redirects. Branch on error_kind, not on error text. TLS is implemented and verified; an https destination is refused rather than downgraded if the handshake fails."""
        return self._call("network.get", url, timeout_ms)

    def network_post(self, url, body, timeout_ms):
        return self._call("network.post", url, body, timeout_ms)

    # --- Ws (capability: network) ---
    def ws_connect(self, url, timeout_ms):
        """WebSocket client. Requires a network grant scoped to the host, and the same egress policy `network.get` uses: a ws:// URL to a private or reserved host is refused, and wss:// fails closed because TLS is not implemented. A connection is addressed by an integer handle; the frames a peer sends are buffered in order and read with `ws.poll` after `ws.pump`. Every call runs on the script worker (blocking reads are expected there). `ws.connect` returns 0 and raises on a refused destination or a failed handshake. `ws.poll` returns {ok, opcode, data, binary}; `ok` is false when the inbox is empty."""
        return self._call("ws.connect", url, timeout_ms)

    def ws_send_text(self, handle, text):
        return self._call("ws.send_text", handle, text)

    def ws_send_binary(self, handle, data):
        return self._call("ws.send_binary", handle, data)

    def ws_pump(self):
        """Reads any pending frames for every open handle into their inboxes. Returns how many frames were read."""
        return self._call("ws.pump")

    def ws_poll(self, handle):
        """Pops the oldest buffered frame for `handle`. `ok` is false when the inbox is empty or the handle is unknown."""
        return self._call("ws.poll", handle)

    def ws_pending(self, handle):
        return self._call("ws.pending", handle)

    def ws_is_open(self, handle):
        return self._call("ws.is_open", handle)

    def ws_close(self, handle):
        return self._call("ws.close", handle)

    def ws_count(self):
        return self._call("ws.count")

    def ws_url(self, handle):
        """The URL a handle was opened with, or \'\' when the handle is unknown."""
        return self._call("ws.url", handle)

    # --- JsonRpc (capability: network) ---
    def json_rpc_call(self, url, method, params_json, timeout_ms):
        """JSON-RPC 2.0 client. Issues one call over the same egress-checked HTTP path as `network.post`, so the destination rules are identical. The response is validated as JSON-RPC 2.0 and its id must match before the result is trusted. `call` returns {ok, result, error_code, error_message, status}: `result` is a structured table decoded from the reply's `result` member, and a transport failure (bad URL, refused destination, HTTP status, malformed envelope) comes back with `ok` false and `error_message` set, so a script branches on the outcome rather than unwinding. `params_json` is raw JSON (an object or array); an empty string omits `params`."""
        return self._call("json_rpc.call", url, method, params_json, timeout_ms)

